(function() {
  var _sentiment = '';

  window.openFeedbackBox = function(type) {
    _sentiment = type;
    var box    = document.getElementById('feedbackBox');
    var title  = document.getElementById('feedbackBoxTitle');
    var btnYes = document.querySelector('.feedback-widget__btn--yes');
    var btnNo  = document.querySelector('.feedback-widget__btn--no');

    // Plausible tracking
    if (window.plausible) {
      plausible('Feedback', { props: { type: type === 'yes' ? 'like' : 'dislike', page: 'budapest' } });
    }

    title.textContent = type === 'yes'
      ? 'תודה רבה על הפידבק, אשמח לשמוע מה אהבת'
      : 'תודה רבה על הפידבק, אשמח לדעת במה נוכל להשתפר באתר';

    box.classList.add('open');

    // Re-parse twemoji on the newly shown title
    if (window.twemoji) {
      twemoji.parse(title, {
        folder: 'svg', ext: '.svg',
        base: 'https://cdn.jsdelivr.net/gh/twitter/twemoji@14.0.2/assets/'
      });
    }

    btnYes.classList.toggle('dimmed', type !== 'yes');
    btnNo.classList.toggle('dimmed',  type !== 'no');

    setTimeout(function() {
      box.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }, 100);
  };

  window.sendFeedback = function() {
    var text = document.getElementById('feedbackText').value.trim();
    var btn  = document.getElementById('feedbackSendBtn');

    btn.textContent = 'שולח...';
    btn.disabled = true;

    fetch('https://formspree.io/f/xdablvpv', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      body: JSON.stringify({
        sentiment: _sentiment === 'yes' ? '👍 חיובי' : '👎 שלילי',
        message:   text || '(ללא הודעה)',
        page:      'budapest'
      })
    })
    .then(function(res) {
      if (!res.ok) throw new Error('שגיאה');

      // Plausible tracking
      if (window.plausible) {
        plausible('Feedback Sent', { props: { type: _sentiment === 'yes' ? 'like' : 'dislike', page: 'budapest' } });
      }

      document.getElementById('feedbackSendBtn').style.display  = 'none';
      document.getElementById('feedbackText').style.display     = 'none';
      document.getElementById('feedbackBoxTitle').style.display = 'none';
      document.getElementById('feedbackThanks').style.display   = 'block';
    })
    .catch(function() {
      btn.textContent = 'שליחה ←';
      btn.disabled = false;
      alert('אירעה שגיאה, נסו שוב.');
    });
  };
})();

(function () {
    var BU = {
      temps: [-1, 1, 6, 12, 16, 20, 22, 21, 16, 10, 5, 0],
      rainDays: [12, 11, 11, 11, 12, 11, 10, 10, 10, 11, 12, 13]
    };
    var months = ['ינו', 'פבר', 'מרץ', 'אפר', 'מאי', 'יונ', 'יול', 'אוג', 'ספט', 'אוק', 'נוב', 'דצמ'];
    var host = document.getElementById('climate-chart-svg-host-bu');
    var tbody = document.getElementById('climate-table-body-bu');
    if (!host) return;
    var W = 720;
    var H = 268;
    var padL = 52;
    var padR = 20;
    var padT = 24;
    var padB = 46;
    var plotW = W - padL - padR;
    var plotH = H - padT - padB;
    var tMin = -6;
    var tMax = 28;
    var baseY = padT + plotH;
    var barMaxH = plotH * 0.4;
    function yTemp(t) {
      return padT + ((tMax - t) / (tMax - tMin)) * plotH;
    }
    function barHeight(d) {
      return (d / 15) * barMaxH;
    }
    var cur = new Date().getMonth();
    var colW = plotW / 12;
    var bw = Math.min(27, colW - 5);

    var defs = '<defs><linearGradient id="buRainGrad" x1="0" y1="1" x2="0" y2="0"><stop offset="0%" stop-color="#124d52"/><stop offset="100%" stop-color="#3d9ea8"/></linearGradient></defs>';

    var gridLines = '';
    [0, 10, 20].forEach(function (mark) {
      if (mark < tMin || mark > tMax) return;
      var gy = yTemp(mark);
      gridLines += '<line x1="' + padL + '" y1="' + gy + '" x2="' + (padL + plotW) + '" y2="' + gy + '" stroke="#e5dfd4" stroke-width="1" stroke-dasharray="5 7"/>';
      gridLines += '<text x="' + (padL - 10) + '" y="' + (gy + 4) + '" text-anchor="end" font-size="11" fill="#888" font-family="Rubik,Arial,sans-serif">' + mark + '°</text>';
    });

    var bars = BU.rainDays.map(function (d, i) {
      var cx = padL + (i + 0.5) * colW;
      var h = barHeight(d);
      var stroke = i === cur ? '#1A6B72' : 'none';
      var sw = i === cur ? 2 : 0;
      return '<rect x="' + (cx - bw / 2) + '" y="' + (baseY - h) + '" width="' + bw + '" height="' + h + '" rx="4" fill="url(#buRainGrad)" opacity="' + (i === cur ? '1' : '0.9') + '" stroke="' + stroke + '" stroke-width="' + sw + '"/>';
    }).join('');

    var pts = BU.temps.map(function (t, i) {
      var cx = padL + (i + 0.5) * colW;
      return cx + ',' + yTemp(t);
    }).join(' ');

    var monthLabels = BU.temps.map(function (_, i) {
      var cx = padL + (i + 0.5) * colW;
      var fw = i === cur ? '700' : '500';
      var fill = i === cur ? '#124d52' : '#5a5a5a';
      return '<text x="' + cx + '" y="' + (H - 12) + '" text-anchor="middle" font-size="11" font-weight="' + fw + '" fill="' + fill + '" font-family="Rubik,Arial,sans-serif">' + months[i] + '</text>';
    }).join('');

    var circles = BU.temps.map(function (t, i) {
      var cx = padL + (i + 0.5) * colW;
      var cy = yTemp(t);
      var r = i === cur ? 5 : 4;
      return '<circle cx="' + cx + '" cy="' + cy + '" r="' + r + '" fill="#fff" stroke="#c4872e" stroke-width="2.5"/>';
    }).join('');

    host.innerHTML =
      '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="xMidYMid meet">' +
      defs + gridLines + bars +
      '<polyline fill="none" stroke="#E8A045" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" points="' + pts + '"/>' +
      circles + monthLabels +
      '</svg>';

    if (tbody) {
      tbody.innerHTML = BU.temps
        .map(function (t, i) {
          var rowClass = i === cur ? ' class="row--current"' : '';
          return '<tr' + rowClass + '><th scope="row">' + months[i] + '</th><td>' + t + '</td><td>' + BU.rainDays[i] + '</td></tr>';
        })
        .join('');
    }
  })();

