(function () {
  var root = document.getElementById('budapest-near-daytrips');
  if (!root) return;
  function setFlipped(card, on) {
    card.classList.toggle('is-flipped', on);
    card.setAttribute('aria-expanded', on ? 'true' : 'false');
  }
  root.querySelectorAll('.beyond-flip').forEach(function (card) {
    card.addEventListener('click', function (e) {
      if (e.target.closest('.beyond-flip__close-btn')) {
        e.preventDefault();
        e.stopPropagation();
        setFlipped(card, false);
        return;
      }
      if (card.classList.contains('is-flipped')) {
        setFlipped(card, false);
        return;
      }
      setFlipped(card, true);
    });
    card.addEventListener('keydown', function (e) {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      e.preventDefault();
      setFlipped(card, !card.classList.contains('is-flipped'));
    });
  });
})();

(function() {
  var openBtn = document.getElementById('pbOpenBtn');
  var closeBtn = document.getElementById('pbCloseBtn');
  var drawer = document.getElementById('pbDrawer');
  var overlay = document.getElementById('pbOverlay');

  function openPb() {
    drawer.classList.add('open');
    overlay.classList.add('open');
    if (window.__mtRefreshBodyScrollLock) window.__mtRefreshBodyScrollLock();
    else document.body.style.overflow = 'hidden';
    if (window.__mtScheduleLeafletInvalidate) window.__mtScheduleLeafletInvalidate();
  }
  function closePb() {
    drawer.classList.remove('open');
    overlay.classList.remove('open');
    if (window.__mtRefreshBodyScrollLock) window.__mtRefreshBodyScrollLock();
    else document.body.style.overflow = '';
    if (window.__mtScheduleLeafletInvalidate) window.__mtScheduleLeafletInvalidate();
  }

  /* ── DRAG ── */
  var isDragging = false;
  var didDrag = false;
  var startX, startY, startLeft, startTop;

  function getPos() {
    var r = openBtn.getBoundingClientRect();
    return { left: r.left, top: r.top };
  }

  function onDragStart(e) {
    var clientX = e.touches ? e.touches[0].clientX : e.clientX;
    var clientY = e.touches ? e.touches[0].clientY : e.clientY;
    var pos = getPos();
    startX = clientX; startY = clientY;
    startLeft = pos.left; startTop = pos.top;
    isDragging = true; didDrag = false;
    openBtn.classList.add('dragging');
    openBtn.style.animation = 'none';
    openBtn.style.bottom = 'auto';
    openBtn.style.left = startLeft + 'px';
    openBtn.style.top = startTop + 'px';
    e.preventDefault();
  }

  function onDragMove(e) {
    if (!isDragging) return;
    var clientX = e.touches ? e.touches[0].clientX : e.clientX;
    var clientY = e.touches ? e.touches[0].clientY : e.clientY;
    var dx = clientX - startX;
    var dy = clientY - startY;
    if (Math.abs(dx) > 3 || Math.abs(dy) > 3) didDrag = true;
    var newLeft = Math.max(8, Math.min(window.innerWidth - openBtn.offsetWidth - 8, startLeft + dx));
    var newTop  = Math.max(8, Math.min(window.innerHeight - openBtn.offsetHeight - 8, startTop + dy));
    openBtn.style.left = newLeft + 'px';
    openBtn.style.top  = newTop + 'px';
    e.preventDefault();
  }

  function onDragEnd(e) {
    if (!isDragging) return;
    isDragging = false;
    openBtn.classList.remove('dragging');
    if (!didDrag) { openPb(); openBtn.style.animation = ''; }
  }

  openBtn.addEventListener('mousedown', onDragStart);
  openBtn.addEventListener('touchstart', onDragStart, { passive: false });
  document.addEventListener('mousemove', onDragMove);
  document.addEventListener('touchmove', onDragMove, { passive: false });
  document.addEventListener('mouseup', onDragEnd);
  document.addEventListener('touchend', onDragEnd);
  closeBtn.addEventListener('click', closePb);
  overlay.addEventListener('click', closePb);
  overlay.addEventListener('touchend', function (e) {
    if (e.target === overlay) closePb();
  }, { passive: true });
  document.addEventListener('keydown', function(e){ if(e.key==='Escape') closePb(); });

  window.pbFilter = function(cat, btn) {
    document.querySelectorAll('.pb-dcat').forEach(function(b){ b.classList.remove('active'); });
    btn.classList.add('active');
    var body = drawer.querySelector('.pb-drawer-body');
    body.querySelectorAll('.pb-item, .pb-section-label, .pb-emergency-note').forEach(function(el){
      var elCat = el.dataset.cat;
      el.style.display = (cat === 'all' || elCat === cat) ? '' : 'none';
    });
  };
})();

