(function () {
  var LAT = 47.4979;
  var LNG = 19.0402;
  var TZ = "Europe/Budapest";

  function wmoIcon(c) {
    var n = Number(c);
    if (n === 0) return "☀️";
    if (n <= 3) return "⛅";
    if (n <= 48) return "🌫";
    if (n <= 57) return "🌦";
    if (n <= 67) return "🌧";
    if (n <= 77) return "❄️";
    if (n <= 82) return "🌧";
    return "⛈";
  }

  function fmtDateParts(iso) {
    try {
      var d = new Date(iso + "T12:00:00");
      return {
        wk: d.toLocaleDateString("he-IL", { weekday: "short" }),
        dm: d.toLocaleDateString("he-IL", { day: "numeric", month: "short" }),
      };
    } catch (e) {
      return { wk: "", dm: iso };
    }
  }

  function fetchJSON(url, ms) {
    var ctrl = new AbortController();
    var t = setTimeout(function () {
      ctrl.abort();
    }, ms);
    return fetch(url, { signal: ctrl.signal })
      .then(function (r) {
        return r.json();
      })
      .finally(function () {
        clearTimeout(t);
      });
  }

  /** טיפ לבוש; משפט עורך אופציונלי מ־data-wear-note על #atWeatherRoot */
  function wearBulletsHe(days, editorialRaw) {
    if (!days || !days.length) return [];
    var editorial = String(editorialRaw || "").trim();
    var n = days.length;
    var minMin = Math.min.apply(
      null,
      days.map(function (d) {
        return d.min;
      })
    );
    var maxMax = Math.max.apply(
      null,
      days.map(function (d) {
        return d.max;
      })
    );
    var maxRain = Math.max.apply(
      null,
      days.map(function (d) {
        return d.rain;
      })
    );
    var avgSpread =
      days.reduce(function (acc, d) {
        return acc + (d.max - d.min);
      }, 0) / n;
    var rainyDays45 = days.filter(function (d) {
      return d.rain >= 45;
    }).length;
    var hasSnow = days.some(function (d) {
      var c = d.code;
      return (c >= 71 && c <= 77) || c === 85 || c === 86;
    });
    var stormLikely = days.some(function (d) {
      return d.code >= 95;
    });
    var spreadWide = avgSpread >= 9 || maxMax - minMin >= 15;

    var bullets = [];

    if (hasSnow || minMin <= -2) {
      bullets.push({
        main: "מעיל חם, כובע, כפפות ונעליים אטומות למים - מתאים לקור חזק ואולי תנאים שלגיים.",
        hint: "כדאי במיוחד לטיולים קצרים בחוץ עם ילדים; בהרים ובגובה זה קורה מהר יותר מאשר בעיר.",
      });
    } else if (minMin <= 5) {
      bullets.push({
        main: "שכבה חמה (ג׳קט או פליז), צעיף או צווארון ומכנסיים ארוכים - דגש על בוקר וערב.",
        hint: "בטווח הזה יש ימים שיורדים עד כ-" + minMin + "° לפחות פעם אחת.",
      });
    } else if (maxMax <= 14 && minMin <= 10) {
      bullets.push({
        main: "מעיל עירוני חם, סווטשירט ונעלי הליכה סגורות - החלון הקריר שולט ברוב הימים.",
        hint: "נוח למוזיאונים ולעיר; אם יוצאים לאגם או להר תוסיפו שכבה.",
      });
    } else if (maxMax >= 28 && minMin >= 14) {
      bullets.push({
        main: "ביגוד קל ונושם, כובע לשמש וקרם הגנה - ימים חמימים יחסית.",
        hint: "עדיין כדאי ג׳קט דק למיזוג או לערב קריר.",
      });
    } else if (maxMax >= 22 && minMin >= 8) {
      bullets.push({
        main: "חולצות קלות וג׳קט דק בתיק - טמפרטורות נעימות אבל משתנות.",
        hint:
          "התחזית ל-" +
          n +
          " ימים — נקודת ייחוס עירונית; באזור בלטון ובצפון לעיתים קריר או חם אחרת מהעיר.",
      });
    } else {
      bullets.push({
        main:
          "שכבות שאפשר לפשוט בצהריים ולהתעטף בערב - טווח בערך בין " +
          minMin +
          "° ל-" +
          maxMax +
          "°.",
        hint:
          "התחזית ל-" +
          n +
          " ימים; באזור בלטון או בהרים צפוניים תכננו לבוש מחמם או שונה מהעיר.",
      });
    }

    if (spreadWide && bullets.length && bullets[0].main.indexOf("שכבות") === -1) {
      bullets[0].hint =
        ((bullets[0].hint || "") +
          " הפרש יום-לילה משמעותי בתחזית - עדיף כמה שכבות דקות מפריט אחד כבד.").trim();
    }

    if (maxRain >= 70 || rainyDays45 >= 3) {
      bullets.push({
        main: "מעיל דוחה מים או גשם עם קפוצ׳ון, ומטריה קומפקטית בתיק.",
        hint:
          "כמה ימים עם סיכוי גבוה; האחוז הוא המקסימום היומי מהמודל - לא אומר גשם רציף כל היום.",
      });
    } else if (maxRain >= 38 || rainyDays45 >= 1) {
      bullets.push({
        main: "קילוי גשם קל או מטריה צפה - לטיפטוף או לממטר קצר.",
        hint: "לא חייבים להסתובב עם מעיל כבד כל הזמן, אבל בתיק זה משכך הפתעות עם ילדים.",
      });
    }

    if (stormLikely) {
      bullets.push({
        main: "תכננו גם פעילות מקורה חלופית לילדים.",
        hint: "לפי המודל ייתכנו ברקים או סופות - כדאי לעקוב אחר התראות מקומיות באותו יום.",
      });
    }

    if (editorial) {
      bullets.push({
        main: editorial,
        hint: "",
      });
    }

    return bullets;
  }

  function renderWearBullets(listEl, bullets) {
    listEl.innerHTML = "";
    if (!bullets.length) return;
    bullets.forEach(function (b) {
      var li = document.createElement("li");
      li.className = "at-weather__wear-item";
      var mainEl = document.createElement("span");
      mainEl.className = "at-weather__wear-li-main";
      mainEl.textContent = b.main;
      li.appendChild(mainEl);
      if (b.hint) {
        var hintEl = document.createElement("span");
        hintEl.className = "at-weather__wear-li-hint";
        hintEl.textContent = b.hint;
        li.appendChild(hintEl);
      }
      listEl.appendChild(li);
    });
  }

  function renderDrawerForecast(containerEl, today, gridDays) {
    if (!containerEl) return;
    var html =
      '<div class="at-drawer-fc-block at-drawer-fc-block--today">' +
      '<div class="at-drawer-fc-kicker">היום</div>' +
      '<div class="at-drawer-fc-icon" aria-hidden="true">' +
      today.icon +
      "</div>" +
      '<div class="at-drawer-fc-temps" dir="ltr">' +
      today.max +
      "° / " +
      today.min +
      "° · גשם " +
      today.rain +
      "%</div></div>";
    gridDays.forEach(function (day) {
      var fd = fmtDateParts(day.date);
      html +=
        '<div class="at-drawer-fc-row">' +
        '<span class="at-drawer-fc-row-date">' +
        fd.wk +
        " · " +
        fd.dm +
        '</span><span class="at-drawer-fc-row-icon" aria-hidden="true">' +
        day.icon +
        '</span><span class="at-drawer-fc-row-temp" dir="ltr">' +
        day.max +
        "°/" +
        day.min +
        '</span><span class="at-drawer-fc-row-rain">' +
        day.rain +
        "%</span></div>";
    });
    containerEl.innerHTML = html;
  }

  var iconEl = document.getElementById("atWeatherTodayIcon");
  var wearWrap = document.getElementById("atWeatherWearWrap");
  var wearListEl = document.getElementById("atWeatherWearList");
  var weatherRoot = document.getElementById("atWeatherRoot");
  var drawerEl = document.getElementById("atWeatherDrawer");
  var drawerBackdrop = document.getElementById("atWeatherDrawerBackdrop");
  var drawerClose = document.getElementById("atWeatherDrawerClose");
  var drawerForecastEl = document.getElementById("atWeatherDrawerForecast");

  if (!weatherRoot) return;

  function closeWeatherDrawer() {
    if (!drawerEl) return;
    drawerEl.classList.remove("at-weather-drawer--open");
    drawerEl.setAttribute("aria-hidden", "true");
    document.body.style.overflow = "";
  }

  function openWeatherDrawer(trackProps) {
    if (!drawerEl || weatherRoot.classList.contains("at-weather--failed")) return;
    if (!weatherRoot.classList.contains("at-weather--ready")) return;
    drawerEl.classList.add("at-weather-drawer--open");
    drawerEl.setAttribute("aria-hidden", "false");
    document.body.style.overflow = "hidden";
    if (drawerClose && typeof drawerClose.focus === "function") drawerClose.focus();
    if (trackProps && window.plausible) {
      try {
        plausible("Budapest-Weather-Drawer-Open", { props: trackProps });
      } catch (ex) {}
    }
  }

  if (drawerBackdrop) drawerBackdrop.addEventListener("click", closeWeatherDrawer);
  if (drawerClose) drawerClose.addEventListener("click", closeWeatherDrawer);
  document.addEventListener("keydown", function (e) {
    if (e.key !== "Escape") return;
    if (drawerEl && drawerEl.classList.contains("at-weather-drawer--open")) closeWeatherDrawer();
  });

  var todayIconBtn = document.getElementById("atWeatherTodayIconBtn");
  if (todayIconBtn) {
    todayIconBtn.addEventListener("click", function () {
      openWeatherDrawer({ page: "budapest", trigger: "today" });
    });
  }

  var url =
    "https://api.open-meteo.com/v1/forecast?latitude=" +
    LAT +
    "&longitude=" +
    LNG +
    "&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max,weathercode" +
    "&forecast_days=5&timezone=" +
    encodeURIComponent(TZ);

  fetchJSON(url, 9000)
    .then(function (data) {
      weatherRoot.classList.remove("at-weather--failed");
      weatherRoot.classList.add("at-weather--ready");
      var d = data && data.daily;
      if (!d || !d.time || !d.time.length) throw new Error("nodata");
      var days = d.time.map(function (date, i) {
        return {
          date: date,
          max: Math.round(d.temperature_2m_max[i] ?? 0),
          min: Math.round(d.temperature_2m_min[i] ?? 0),
          rain: Math.round(d.precipitation_probability_max[i] ?? 0),
          icon: wmoIcon(d.weathercode[i] ?? 0),
          code: Number(d.weathercode[i] ?? 0),
        };
      });
      var today = days[0];
      if (iconEl) iconEl.textContent = today.icon;
      if (todayIconBtn) {
        todayIconBtn.setAttribute(
          "aria-label",
          "תחזית היום: מקסימום " +
            today.max +
            " מעלות, מינימום " +
            today.min +
            " מעלות, סיכוי גשם " +
            today.rain +
            "% · פתיחת פרטים וטיפ לבוש"
        );
      }
      var editorialNote =
        weatherRoot && typeof weatherRoot.getAttribute === "function"
          ? weatherRoot.getAttribute("data-wear-note") || ""
          : "";
      var gridDays = days.slice(1, 5);
      if (wearListEl && wearWrap) {
        renderWearBullets(wearListEl, wearBulletsHe(days, editorialNote));
      }
      renderDrawerForecast(drawerForecastEl, today, gridDays);
    })
    .catch(function () {
      if (weatherRoot) {
        weatherRoot.classList.add("at-weather--failed");
        weatherRoot.classList.remove("at-weather--ready");
      }
      closeWeatherDrawer();
      if (iconEl) iconEl.textContent = "\u2014";
      if (todayIconBtn) todayIconBtn.setAttribute("aria-label", "לא ניתן לטעון תחזית כרגע");
      if (wearListEl) wearListEl.innerHTML = "";
      if (drawerForecastEl) drawerForecastEl.innerHTML = "";
    });
})();

